CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, salt TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'client', created TEXT NOT NULL);
CREATE TABLE sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
CREATE TABLE leads (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id), name TEXT NOT NULL, contact TEXT NOT NULL, service TEXT NOT NULL, description TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Заявка получена', price INTEGER NOT NULL DEFAULT 0, due TEXT NOT NULL DEFAULT '', created TEXT NOT NULL);
CREATE TABLE messages (id TEXT PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES leads(id), user_id TEXT NOT NULL REFERENCES users(id), text TEXT NOT NULL, created TEXT NOT NULL);
CREATE TABLE estimates (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, data TEXT NOT NULL, total INTEGER NOT NULL, created TEXT NOT NULL);
CREATE TABLE content (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
